(defn getcmdline ^BytePtr [^Editor ed firstc count_ indent do-concat]
  (let [firstc (long firstc)
        count_ (long count_)
        indent (long indent)
        do-concat (long do-concat)]
    (getcmdline-int ed firstc count_ indent true)))

(defn getexline ^BytePtr [^Editor ed ^long c ^long indent ^long options]
  (if (and (not (zero? (g ed exec-from-reg))) (== (long (vpeekc ed)) 58))
    (do (vgetc ed)
        (getcmdline ed c 1 indent options))
    (getcmdline ed c 1 indent options)))

;; C: ex_at
(defn ex-at [^Editor ed ^S_exarg eap]
  (let [prev-len (.tb-len (g ed typebuf))
        _ (.set-lnum ^T_pos_T (.-w-cursor (g ed curwin)) (.line2 eap))
        _ (check-cursor-col ed)
        c (.ub ^BytePtr (aget ^objects (.-arg eap) 0))
        c (if (or (== c (e NUL)) (and (== c 42) (== (.ub ^BytePtr (aget ^objects (.-cmd eap) 0)) 42)))
            64
            c)]
    (if (do-execreg ed c true (some? (vim-strchr ed (aget (g ed p-cpo) 0) (e CPO_EXECBUF))) true)
      (let [save-efr (g ed exec-from-reg)]
        (g! ed exec-from-reg (e TRUE))
        (loop []
          (if (or (not (stuff-empty? ed)) (> (.tb-len (g ed typebuf)) prev-len))
            (do (do-cmdline ed nil getexline 67)
                (recur))
            (do (g! ed exec-from-reg save-efr)
                nil))))
      (do (beep-flush ed)
          nil))))

;; C: u_undoredo
(defn u-undoredo [^Editor ed undo]
  (let [^objects namedm (array-T_pos_T 26)
        ^T_visualinfo_T visualinfo (new-T_visualinfo_T)]
    (loop [st 0
           undo undo
           ^Ptr newarray nil
           oldsize 0
           newsize 0
           top 0
           bot 0
           lnum 0
           newlnum 0
           new-curpos-lnum 0
           new-curpos-col 0
           new-curpos-coladd 0
           i 0
           ^S_u_entry uep nil
           ^S_u_entry newlist nil
           old-flags 0
           new-flags 0
           empty-buffer false
           ^S_u_header curhead nil]
      (case st
        0
          (let [^Ptr newarray nil
                newlnum (e LONG_MAX)
                new-curpos-lnum (.lnum ^T_pos_T (.-w-cursor (g ed curwin)))
                new-curpos-col (.col ^T_pos_T (.-w-cursor (g ed curwin)))
                new-curpos-coladd (.coladd ^T_pos_T (.-w-cursor (g ed curwin)))
                ^S_u_entry newlist nil
                ^S_u_header curhead (.b-u-curhead (g ed curbuf))
                _ (block-autocmds ed)
                old-flags (.uh-flags curhead)
                new-flags (i32 (+ (if (zero? (long (aget ^ints (.-b-changed (g ed curbuf)) 0))) 0 (e UH_CHANGED)) (if (zero? (bit-and (.ml-flags ^S_memline (.-b-ml (g ed curbuf))) (e ML_EMPTY))) 0 (e UH_EMPTYBUF))))
                _ (setpcmark ed)
                _ (Rt/moveStructs (Ptr. namedm 0) (Ptr. ^objects (.-b-namedm (g ed curbuf)) 0) 26)
                _ (.set visualinfo (.-b-visual (g ed curbuf)))
                _ (.set-lnum ^T_pos_T (.-b-op-start (g ed curbuf)) (.ml-line-count ^S_memline (.-b-ml (g ed curbuf))))
                _ (.set-col ^T_pos_T (.-b-op-start (g ed curbuf)) 0)
                _ (.set-lnum ^T_pos_T (.-b-op-end (g ed curbuf)) 0)
                _ (.set-col ^T_pos_T (.-b-op-end (g ed curbuf)) 0)
                ^S_u_entry uep (.uh-entry curhead)]
            (recur 1 undo newarray oldsize newsize top bot lnum newlnum new-curpos-lnum new-curpos-col new-curpos-coladd i uep newlist old-flags new-flags empty-buffer curhead))
        1
          (if (some? uep)
            (let [top (.ue-top uep)
                  bot (.ue-bot uep)
                  bot (if (== bot 0)
                        (+ (.ml-line-count ^S_memline (.-b-ml (g ed curbuf))) 1)
                        bot)]
              (if (or (> top (.ml-line-count ^S_memline (.-b-ml (g ed curbuf)))) (>= top bot) (> bot (+ (.ml-line-count ^S_memline (.-b-ml (g ed curbuf))) 1)))
                (do (unblock-autocmds ed)
                    (iemsg ed (BytePtr. (g ed e-u-undo-line-numbers-wrong) 0))
                    (changed ed)
                    nil)
                (let [oldsize (- (- bot top) 1)
                      newsize (.ue-size uep)
                      lnum (.lnum ^T_pos_T (.-uh-cursor curhead))]
                  (if (and (>= lnum top) (<= lnum (+ top newsize 1)))
                    (let [new-curpos-lnum (.lnum ^T_pos_T (.-uh-cursor curhead))
                          new-curpos-col (.col ^T_pos_T (.-uh-cursor curhead))
                          new-curpos-coladd (.coladd ^T_pos_T (.-uh-cursor curhead))
                          newlnum -1]
                      (recur 5 undo newarray oldsize newsize top bot lnum newlnum new-curpos-lnum new-curpos-col new-curpos-coladd i uep newlist old-flags new-flags empty-buffer curhead))
                    (if (< top newlnum)
                      (let [i 0]
                        (recur 3 undo newarray oldsize newsize top bot lnum newlnum new-curpos-lnum new-curpos-col new-curpos-coladd i uep newlist old-flags new-flags empty-buffer curhead))
                      (recur 5 undo newarray oldsize newsize top bot lnum newlnum new-curpos-lnum new-curpos-col new-curpos-coladd i uep newlist old-flags new-flags empty-buffer curhead))))))
            (do (when (> (.lnum ^T_pos_T (.-b-op-start (g ed curbuf))) (.ml-line-count ^S_memline (.-b-ml (g ed curbuf))))
                  (.set-lnum ^T_pos_T (.-b-op-start (g ed curbuf)) (.ml-line-count ^S_memline (.-b-ml (g ed curbuf)))))
                (when (> (.lnum ^T_pos_T (.-b-op-end (g ed curbuf))) (.ml-line-count ^S_memline (.-b-ml (g ed curbuf))))
                  (.set-lnum ^T_pos_T (.-b-op-end (g ed curbuf)) (.ml-line-count ^S_memline (.-b-ml (g ed curbuf)))))
                (.set-lnum ^T_pos_T (.-w-cursor (g ed curwin)) new-curpos-lnum)
                (.set-col ^T_pos_T (.-w-cursor (g ed curwin)) new-curpos-col)
                (.set-coladd ^T_pos_T (.-w-cursor (g ed curwin)) new-curpos-coladd)
                (check-cursor-lnum ed)
                (.set-uh-entry curhead newlist)
                (.set-uh-flags curhead new-flags)
                (when (and (not (zero? (bit-and old-flags (e UH_EMPTYBUF)))) (== (.ml-line-count ^S_memline (.-b-ml (g ed curbuf))) 1) (== (.ub ^BytePtr (ml-get ed 1)) (e NUL)))
                  (.set-ml-flags ^S_memline (.-b-ml (g ed curbuf)) (bit-or (.ml-flags ^S_memline (.-b-ml (g ed curbuf))) (e ML_EMPTY))))
                (if (zero? (bit-and old-flags (e UH_CHANGED)))
                  (unchanged ed (g ed curbuf) false true)
                  (changed ed))
                (let [i 0]
                  (recur 2 undo newarray oldsize newsize top bot lnum newlnum new-curpos-lnum new-curpos-col new-curpos-coladd i uep newlist old-flags new-flags empty-buffer curhead))))
        2
          (if (< i 26)
            (do (when-not (== (.lnum ^T_pos_T (aget ^objects (.-uh-namedm curhead) i)) 0)
                  (.set ^T_pos_T (aget ^objects (.-b-namedm (g ed curbuf)) i) (aget ^objects (.-uh-namedm curhead) i)))
                (if (== (.lnum ^T_pos_T (aget namedm i)) 0)
                  (.set-lnum ^T_pos_T (aget ^objects (.-uh-namedm curhead) i) 0)
                  (.set ^T_pos_T (aget ^objects (.-uh-namedm curhead) i) (aget namedm i)))
                (let [i (inc i)]
                  (recur 2 undo newarray oldsize newsize top bot lnum newlnum new-curpos-lnum new-curpos-col new-curpos-coladd i uep newlist old-flags new-flags empty-buffer curhead)))
            (do (when-not (== (.lnum ^T_pos_T (.-vi-start ^T_visualinfo_T (.-uh-visual curhead))) 0)
                  (.set ^T_visualinfo_T (.-b-visual (g ed curbuf)) (.-uh-visual curhead))
                  (.set ^T_visualinfo_T (.-uh-visual curhead) visualinfo))
                (when (and (== (+ (.lnum ^T_pos_T (.-uh-cursor curhead)) 1) (.lnum ^T_pos_T (.-w-cursor (g ed curwin)))) (> (.lnum ^T_pos_T (.-w-cursor (g ed curwin))) 1))
                  (.set-lnum ^T_pos_T (.-w-cursor (g ed curwin)) (dec (.lnum ^T_pos_T (.-w-cursor (g ed curwin))))))
                (if (<= (.lnum ^T_pos_T (.-w-cursor (g ed curwin))) (.ml-line-count ^S_memline (.-b-ml (g ed curbuf))))
                  (if (== (.lnum ^T_pos_T (.-uh-cursor curhead)) (.lnum ^T_pos_T (.-w-cursor (g ed curwin))))
                    (do (.set-col ^T_pos_T (.-w-cursor (g ed curwin)) (.col ^T_pos_T (.-uh-cursor curhead)))
                        (if (and (not (zero? (long (virtual-active ed)))) (>= (.uh-cursor-vcol curhead) 0))
                          (coladvance ed (i32 (.uh-cursor-vcol curhead)))
                          (.set-coladd ^T_pos_T (.-w-cursor (g ed curwin)) 0)))
                    (beginline ed 6))
                  (do (.set-col ^T_pos_T (.-w-cursor (g ed curwin)) 0)
                      (.set-coladd ^T_pos_T (.-w-cursor (g ed curwin)) 0)))
                (check-cursor ed)
                (.set-b-u-seq-cur (g ed curbuf) (.uh-seq curhead))
                (when undo
                  (if (some? (.uh-next curhead))
                    (.set-b-u-seq-cur (g ed curbuf) (.uh-seq ^S_u_header (.uh-next curhead)))
                    (.set-b-u-seq-cur (g ed curbuf) 0)))
                (if (== (.uh-save-nr curhead) 0)
                  (do (.set-b-u-time-cur (g ed curbuf) (.uh-time curhead))
                      (unblock-autocmds ed)
                      nil)
                  (if undo
                    (do (.set-b-u-save-nr-cur (g ed curbuf) (- (.uh-save-nr curhead) 1))
                        (.set-b-u-time-cur (g ed curbuf) (.uh-time curhead))
                        (unblock-autocmds ed)
                        nil)
                    (do (.set-b-u-save-nr-cur (g ed curbuf) (.uh-save-nr curhead))
                        (.set-b-u-time-cur (g ed curbuf) (.uh-time curhead))
                        (unblock-autocmds ed)
                        nil)))))
        3
          (if (and (< i newsize) (< i oldsize))
            (let [^BytePtr p (ml-get ed (+ top 1 i))]
              (if (or (not (== (.ml-line-len ^S_memline (.-b-ml (g ed curbuf))) (.ul-len ^T_undoline_T (.at ^Ptr (.ue-array uep) i)))) (not (== (long (Rt/memcmp ^BytePtr (.ul-line ^T_undoline_T (.at ^Ptr (.ue-array uep) i)) p (.ml-line-len ^S_memline (.-b-ml (g ed curbuf))))) 0)))
                (recur 4 undo newarray oldsize newsize top bot lnum newlnum new-curpos-lnum new-curpos-col new-curpos-coladd i uep newlist old-flags new-flags empty-buffer curhead)
                (let [i (inc i)]
                  (recur 3 undo newarray oldsize newsize top bot lnum newlnum new-curpos-lnum new-curpos-col new-curpos-coladd i uep newlist old-flags new-flags empty-buffer curhead))))
            (recur 4 undo newarray oldsize newsize top bot lnum newlnum new-curpos-lnum new-curpos-col new-curpos-coladd i uep newlist old-flags new-flags empty-buffer curhead))
        4
          (if (and (== i newsize) (== newlnum (e LONG_MAX)) (nil? (.ue-next uep)))
            (let [newlnum top
                  new-curpos-lnum (+ newlnum 1)]
              (recur 5 undo newarray oldsize newsize top bot lnum newlnum new-curpos-lnum new-curpos-col new-curpos-coladd i uep newlist old-flags new-flags empty-buffer curhead))
            (if (< i newsize)
              (let [newlnum (+ top i)
                    new-curpos-lnum (+ newlnum 1)]
                (recur 5 undo newarray oldsize newsize top bot lnum newlnum new-curpos-lnum new-curpos-col new-curpos-coladd i uep newlist old-flags new-flags empty-buffer curhead))
              (recur 5 undo newarray oldsize newsize top bot lnum newlnum new-curpos-lnum new-curpos-col new-curpos-coladd i uep newlist old-flags new-flags empty-buffer curhead)))
        5
          (let [empty-buffer false]
