              (let [^Ptr newarray nil]
                (recur 7 undo newarray oldsize newsize top bot lnum newlnum new-curpos-lnum new-curpos-col new-curpos-coladd i uep newlist old-flags new-flags empty-buffer curhead))))
        6
          (let [i (dec i)]
            (if (>= i 0)
