;; C: nv_normal
(defn nv-normal [^Editor ed ^S_cmdarg_S cap]
  (if (or (== (long (aget ^ints (.-nchar cap) 0)) (e Ctrl_N)) (== (long (aget ^ints (.-nchar cap) 0)) (e Ctrl_G)))
