          (g! ed clear-cmdline (e TRUE)))
        (g! ed restart-edit 0)
        (when-not (zero? (g ed VIsual-active))
          (end-visual-mode ed)
          (redraw-curbuf-later ed (e UPD_INVERTED)))
        (when (and (== (long (aget ^ints (.-nchar cap) 0)) (e Ctrl_G)) (not (zero? (long (aget (g ed p-im) 0)))))
          (g! ed restart-edit 97)
          nil))
