(defn anyBufIsChanged ^long [^Editor ed]
  (long (bufIsChanged ed (g ed curbuf))))

;; C: nv_esc
(defn nv-esc [^Editor ed ^S_cmdarg_S cap]
  (let [no-reason (and (== (.op-type ^S_oparg_S (.oap cap)) (e OP_NOP)) (== (.opcount cap) 0) (== (.count0 cap) 0) (== (.regname ^S_oparg_S (.oap cap)) 0) (zero? (long (aget (g ed p-im) 0))))]
    (when-not (zero? (.arg cap))
      (when (and (== (g ed restart-edit) 0) (zero? (g ed VIsual-active)) no-reason)
        (if (zero? (long (anyBufIsChanged ed)))
          (msg ed (gettext_ ed (BytePtr/lit "Type  :qa  and press <Enter> to exit Vim")))
          (let [^BytePtr ms (gettext_ ed (BytePtr/lit "Type  :qa!  and press <Enter> to abandon all changes and exit Vim"))]
            (msg ed ms))))
      (when-not (== (g ed restart-edit) 0)
        (g! ed redraw-mode (e TRUE)))
      (when (zero? (long (aget (g ed p-im) 0)))
        (g! ed restart-edit 0)))
    (if (zero? (g ed VIsual-active))
      (when no-reason
        (vim-beep ed (e BO_ESC)))
      (do (end-visual-mode ed)
          (check-cursor-col ed)
          (.set-w-set-curswant (g ed curwin) (boolean true))
          (redraw-curbuf-later ed (e UPD_INVERTED))))
    (clearop ed (.oap cap))
    (when (and (== (g ed restart-edit) 0) (goto-im? ed) (== (g ed ex-normal-busy) 0))
      (g! ed restart-edit 97)
      nil)))

;; C: stuff_yank
(defn stuff-yank [^Editor ed ^long regname ^BytePtr p]
  (if (and (not (== regname 0)) (not (valid-yank-reg ed regname true)))
    false
    (if (== regname 95)
      true
      (let [plen (long (musl-strlen ed p))]
        (get-yank-register ed regname (e TRUE))
        (if (and (not (zero? (g ed y-append))) (some? (.y-array (g ed y-current))))
          (let [^T_string_T pp (Ptr/ref (.add ^Ptr (.y-array (g ed y-current)) (- (.y-size (g ed y-current)) 1)))
                tmplen (+ (.length pp) plen)
                ^BytePtr tmp (BytePtr/alloc (+ tmplen 1))]
            (musl-strcpy ed tmp (aget ^objects (.-string pp) 0))
            (musl-strcpy ed (.add tmp (.length pp)) p)
            (aset ^objects (.-string pp) 0 tmp)
            (.set-length pp tmplen)
            true)
          (do (free-yank-all ed)
              (.set-y-array (g ed y-current) (Ptr. (array-T_string_T 1) 0))
              (aset ^objects (.-string ^T_string_T (.at ^Ptr (.y-array (g ed y-current)) 0)) 0 p)
              (.set-length ^T_string_T (.at ^Ptr (.y-array (g ed y-current)) 0) plen)
              (.set-y-size (g ed y-current) 1)
              (.set-y-type (g ed y-current) (e MCHAR))
              true))))))

;; C: do_record
(defn do-record [^Editor ed ^long c]
  (if (== (g ed reg-recording) 0)
    (if (or (< c 0) (and (not (or (< (u32 (- (u32 c) 65)) 26) (< (u32 (- (u32 c) 97)) 26) (< (u32 (- (u32 c) 48)) 10))) (not (== c 34))))
      false
      (do (g! ed reg-recording c)
          (showmode ed)
          (g! ed do-record-regname c)
          true))
    (do (g! ed reg-recording 0)
        (msg ed (BytePtr/lit ""))
        (let [^BytePtr p (get-recorded ed)]
          (if (nil? p)
            false
            (do (vim-unescape-csi ed p)
                (let [^T_yankreg_T old-y-previous (g ed y-previous)
                      ^T_yankreg_T old-y-current (g ed y-current)
                      retval (stuff-yank ed (g ed do-record-regname) p)]
                  (g! ed y-previous old-y-previous)
                  (g! ed y-current old-y-current)
                  retval)))))))

