                  (let [^BytePtr p (vim-strsave ed (g ed keep-msg))]
                    (g! ed msg-hist-off (e TRUE))
                    (msg-attr ed p (g ed keep-msg-attr))
                    (g! ed msg-hist-off (e FALSE))))
                (when-not (zero? (g ed need-fileinfo))
                  (fileinfo ed (e FALSE) true false)
                  (g! ed need-fileinfo (e FALSE)))
                (g! ed emsg-on-display (e FALSE))
                (g! ed did-emsg (e FALSE))
                (g! ed msg-didany (e FALSE))
                (may-clear-sb-text ed)
                (showruler ed false)
                (setcursor ed)
                (cursor-on ed)
                (g! ed do-redraw (e FALSE))
                (may-make-initial-scroll-size-snapshot ed))
              (do (g! ed skip-redraw (e FALSE))
                  (setcursor ed)
                  (cursor-on ed)))
            (may-send-t-RK ed)
            (update-curswant ed)
            (normal-cmd ed oa true)
            (recur))))))

;; C: vim_main2
(defn vim-main2 ^long [^Editor ed]
  (g! ed starting (e NO_BUFFERS))
  (g! ed no-wait-return (e FALSE))
  (g! ed msg-scroll (e FALSE))
  (when (and (or (not (zero? (g ed did-emsg))) (not (zero? (g ed msg-didout)))) (not (== (.ub ^BytePtr (aget (g ed term-strings) 42)) (e NUL))))
    (g! ed newline-on-exit (e TRUE)))
  (term-enter ed)
  (when (or (not (zero? (g ed need-wait-return))) (not (zero? (g ed msg-didany))))
    (wait-return ed (e TRUE)))
  (starttermcap ed)
  (when-not (zero? (g ed scroll-region))
    (scroll-region-reset ed))
  (scroll-start ed)
  (screenclear ed)
  (g! ed no-wait-return (e TRUE))
  (create-windows ed (g ed params))
  (setpcmark ed)
  (shorten-fnames ed)
  (when (> (.n-commands (g ed params)) 0)
    (exe-commands ed (g ed params)))
  (g! ed starting 0)
  (g! ed RedrawingDisabled 0)
  (redraw-all-later ed (e UPD_NOT_VALID))
  (g! ed no-wait-return (e FALSE))
  (when-not (zero? (long (aget (g ed p-im) 0)))
    (g! ed need-start-insertmode (e TRUE)))
  (if (== (g ed restart-edit) 0)
    (do (g! ed do-redraw (e TRUE))
        (main-loop ed false)
        0)
    (do (stuffcharReadbuff ed (e K_NOP))
        (g! ed do-redraw (e TRUE))
        (main-loop ed false)
        0)))

;; C: common_init_1
(defn common-init-1 [^Editor ed]
  (estack-init ed)
  (cmdline-init ed)
  (let [i 0]
    (loop [i i]
      (if (< i 256)
        (do (aset (g ed mb-bytelen-tab) i (unchecked-byte 1))
            (let [i (i32 (inc i))]
              (recur i)))
        (do (g! ed IObuff (BytePtr/alloc 1025))
            (let [t1 (nil? (g ed IObuff))
                  t1 (if t1
                       t1
                       (do (g! ed NameBuff (BytePtr/alloc (e PATH_MAX)))
                           (nil? (g ed NameBuff))))]
              (when t1
                (mch-exit ed 0)
                nil)))))))

;; C: common_init_2
(defn common-init-2 [^Editor ed ^T_mparm_T paramp]
  (if (win-alloc-first ed)
    (do (init-yank ed)
        (set-init-1 ed)
        nil)
    (do (mch-exit ed 0)
        (init-yank ed)
        (set-init-1 ed)
        nil)))

(defn mainerr [^Editor ed ^long n ^BytePtr str_]
  (let [^bytes buf (byte-array 1024)]
    (init-longVersion ed)
    (if (some? str_)
      (do (whim.cljhost/vim-snprintf ed (BytePtr. buf 0) 1024 (BytePtr/lit "%s\n%s: \"%s\"") (object-array [(g ed longVersion) (gettext_ ed (aget (g ed main-errors) n)) str_]))
          (whim.cljhost/host-message ed (BytePtr. buf 0) -1 (e TRUE))
          (mch-exit ed 1)
          nil)
      (do (whim.cljhost/vim-snprintf ed (BytePtr. buf 0) 1024 (BytePtr/lit "%s\n%s") (object-array [(g ed longVersion) (gettext_ ed (aget (g ed main-errors) n))]))
          (whim.cljhost/host-message ed (BytePtr. buf 0) -1 (e TRUE))
          (mch-exit ed 1)
          nil))))

;; C: command_line_scan
(defn command-line-scan [^Editor ed ^T_mparm_T parmp]
  (let [^longs tl__ (long-array 2)
        ^objects to__ (object-array 1)
        argc (.argc parmp)
        ^Ptr argv (.argv parmp)
        argc (i32 (dec argc))
        ^Ptr argv (.add argv 1)
        argv-idx 1]
    (loop [argc argc
           ^Ptr argv argv
           argv-idx argv-idx]
      (when (> argc 0)
        (let [argv-idx (if (== (long (.at ^BytePtr (.at argv 0) 0)) 43)
                         (do (when (>= (.n-commands parmp) (e MAX_ARG_CMDS))
                               (mainerr ed (e ME_EXTRA_CMD) nil))
                             (let [argv-idx -1]
                               (if (== (long (.at ^BytePtr (.at argv 0) 1)) (e NUL))
                                 (let [t1 (.n-commands parmp)]
                                   (.set-n-commands parmp (i32 (inc (.n-commands parmp))))
                                   (aset ^objects (.-commands parmp) t1 (BytePtr/lit "$"))
                                   argv-idx)
                                 (let [t2 (.n-commands parmp)]
                                   (.set-n-commands parmp (i32 (inc (.n-commands parmp))))
                                   (aset ^objects (.-commands parmp) t2 (.add ^BytePtr (.at argv 0) 1))
                                   argv-idx))))
                         (do (mainerr ed (e ME_UNKNOWN_OPTION) (.at argv 0))
                             argv-idx))
              j__1 (if (or (<= argv-idx 0) (== (long (.at ^BytePtr (.at argv 0) argv-idx)) (e NUL)))
                     (let [argc (i32 (dec argc))
                           ^Ptr argv (.add argv 1)
                           argv-idx 1]
                       (aset tl__ 0 argc)
                       (aset to__ 0 argv)
                       (aset tl__ 1 argv-idx)
                       0)
                     (do (aset tl__ 0 argc)
                         (aset to__ 0 argv)
                         (aset tl__ 1 argv-idx)
                         0))
              argc (aget tl__ 0)
              ^Ptr argv (aget to__ 0)
              argv-idx (aget tl__ 1)]
          (recur argc argv argv-idx))))))

;; C: vim_main
(defn vim-main ^long [^Editor ed ^long argc ^Ptr argv]
  (.zero (g ed params))
  (.set-argc (g ed params) argc)
  (.set-argv (g ed params) argv)
  (.set-want-full-screen (g ed params) (boolean true))
  (common-init-1 ed)
  (common-init-2 ed (g ed params))
  (command-line-scan ed (g ed params))
  (g! ed RedrawingDisabled (i32 (inc (g ed RedrawingDisabled))))
  (mch-init ed)
  (when (.want-full-screen (g ed params))
    (termcapinit ed)
    (screen-start ed))
  (ui-get-shellsize ed)
  (win-init-size ed)
  (g! ed cmdline-row (i32 (- (aget (g ed Rows) 0) (aget (g ed p-ch) 0))))
  (g! ed cmdline-col-off 0)
  (g! ed cmdline-width (i32 (aget (g ed Columns) 0)))
  (g! ed msg-row (g ed cmdline-row))
  (g! ed msg-col 0)
  (screenalloc ed false)
  (set-init-2 ed)
  (g! ed msg-scroll (e TRUE))
  (g! ed no-wait-return (e TRUE))
  (init-mappings ed)
  (init-highlight ed true false)
  (long (vim-main2 ed)))

;; The tables the file-scope arrays of structs start with, as data (clj_tables.go).

(defn- row-long "A number of a table's row: itself, or an enumerator's by its name." ^long [v]
  (if (symbol? v) (long (get enumerators v)) (long v)))

(defn- fill-S_clinterval!
  "Fill the S_clinterval objects of a from rows, a table's: one row an element, nil one left zero."
  [^objects a rows]
  (loop [i 0
         rows (seq rows)]
    (when rows
      (when-some [r (first rows)]
        (let [^S_clinterval o (aget a i)]
          (.set-first_ o (row-long (nth r 0)))
          (.set-last_ o (row-long (nth r 1)))
          (.set-class_ o (row-long (nth r 2)))))
      (recur (inc i) (next rows)))))

